pp=OUT/'unit_predictions.parquet';sp=OUT/'spatial_residual_diagnostics.csv';watched={str(p):sha(p)for p in [pp,sp,BASE/'analysis/cycle07_tools/PROTOCOL_v2.json',OUT/'run_receipt.json']};pred=pd.read_parquet(pp);s=pd.read_csv(sp);cfg=json.loads((BASE/'analysis/cycle07_tools/PROTOCOL_v2.json').read_text());
for (scenario,lev),group in pred.groupby(['scenario','candidate_cap'],sort=True):
 base=pred[pred.scenario.eq(scenario)&pred.candidate_cap.eq(lev)&pred.model.eq('M1')].copy();ids=base.unit_id.tolist();lat=np.radians(base.lat.to_numpy());lon=np.radians(base.lon.to_numpy());dlat=lat[:,None]-lat[None,:];dlon=lon[:,None]-lon[None,:];hav=np.sin(dlat/2)**2+np.cos(lat[:,None])*np.cos(lat[None,:])*np.sin(dlon/2)**2;distance=2*np.arcsin(np.sqrt(np.clip(hav,0,1)));np.fill_diagonal(distance,np.inf);nearest=np.argsort(distance,axis=1,kind='stable')[:,:8];A=np.zeros((len(base),len(base)),bool);A[np.arange(len(base))[:,None],nearest]=True;A=A|A.T;np.fill_diagonal(A,False);W=A/A.sum(axis=1)[:,None];cut=np.sort(distance,axis=1)[:,7];ties=(np.isclose(distance,cut[:,None],atol=1e-12,rtol=1e-12).sum(axis=1)>1)&(np.sum(distance<cut[:,None]-1e-12,axis=1)<8);ck(f'{scenario}:level{lev}:graph_symmetry_rowstd_noisolates',np.array_equal(A,A.T)and np.allclose(W.sum(axis=1),1)and not np.diag(A).any(),{'n_centers':len(base),'boundary_tie_rows':int(ties.sum())})
